-- C10 / P10.3 — immutable social draft revisions with exact asset provenance/rights and approval bindings.
create table if not exists public.command_center_social_draft_revision_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 draft_event_id text not null check(btrim(draft_event_id)<>''),
 draft_id text not null check(btrim(draft_id)<>''), brand_id text not null check(btrim(brand_id)<>''), intended_account_id text not null check(btrim(intended_account_id)<>''),
 draft_version integer not null check(draft_version>0), observed_at timestamptz not null, body text not null check(btrim(body)<>''), content_hash text not null check(btrim(content_hash)<>''),
 source_asset_refs text[] not null default '{}'::text[], rights_evidence_refs text[] not null default '{}'::text[], provenance_refs text[] not null check(cardinality(provenance_refs)>0), approval_refs text[] not null default '{}'::text[], sensitivity_rank integer not null check(sensitivity_rank>=0),
 primary key(owner_id,draft_event_id), unique(owner_id,draft_id,draft_version), unique(owner_id,draft_event_id,draft_id,draft_version,intended_account_id,content_hash)
);
create table if not exists public.command_center_social_draft_asset_bindings (
 owner_id uuid not null, draft_event_id text not null, draft_id text not null, draft_version integer not null, asset_ref text not null check(btrim(asset_ref)<>''), asset_content_hash text not null check(btrim(asset_content_hash)<>''),
 provenance_refs text[] not null check(cardinality(provenance_refs)>0), rights_evidence_refs text[] not null check(cardinality(rights_evidence_refs)>0),
 primary key(owner_id,draft_event_id,asset_ref), foreign key(owner_id,draft_event_id) references public.command_center_social_draft_revision_history(owner_id,draft_event_id) on delete restrict,
 foreign key(owner_id,draft_id,draft_version) references public.command_center_social_draft_revision_history(owner_id,draft_id,draft_version) on delete restrict
);
create table if not exists public.command_center_social_draft_approval_bindings (
 owner_id uuid not null, draft_event_id text not null, draft_id text not null, approved_draft_version integer not null check(approved_draft_version>0), intended_account_id text not null check(btrim(intended_account_id)<>''), approved_content_hash text not null check(btrim(approved_content_hash)<>''),
 approval_ref text not null check(btrim(approval_ref)<>''), approver_ref text not null check(btrim(approver_ref)<>''), approved_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 primary key(owner_id,draft_event_id,approval_ref),
 foreign key(owner_id,draft_event_id,draft_id,approved_draft_version,intended_account_id,approved_content_hash) references public.command_center_social_draft_revision_history(owner_id,draft_event_id,draft_id,draft_version,intended_account_id,content_hash) on delete restrict
);
create or replace view public.command_center_social_drafts_current with (security_invoker=true) as
 select distinct on(owner_id,draft_id) owner_id,draft_event_id,draft_id,brand_id,intended_account_id,draft_version,observed_at,body,content_hash,source_asset_refs,rights_evidence_refs,provenance_refs,approval_refs,sensitivity_rank
 from public.command_center_social_draft_revision_history order by owner_id,draft_id,draft_version desc,observed_at desc;
create or replace function public.command_center_validate_social_draft_asset_binding() returns trigger language plpgsql set search_path to 'public' as $$
declare refs text[]; begin select source_asset_refs into refs from public.command_center_social_draft_revision_history where owner_id=new.owner_id and draft_event_id=new.draft_event_id; if refs is null or not (new.asset_ref=any(refs)) then raise exception 'Asset binding must reference an asset declared by the exact draft revision'; end if; return new; end $$;
create or replace function public.command_center_validate_social_draft_approval_binding() returns trigger language plpgsql set search_path to 'public' as $$
declare refs text[]; revision_observed_at timestamptz; begin select approval_refs,observed_at into refs,revision_observed_at from public.command_center_social_draft_revision_history where owner_id=new.owner_id and draft_event_id=new.draft_event_id; if refs is null or not (new.approval_ref=any(refs)) then raise exception 'Approval binding must reference approval evidence declared by the exact draft revision'; end if; if new.approved_at<revision_observed_at then raise exception 'Approval cannot predate the draft revision'; end if; return new; end $$;
drop trigger if exists command_center_social_draft_asset_binding_validate on public.command_center_social_draft_asset_bindings; create trigger command_center_social_draft_asset_binding_validate before insert on public.command_center_social_draft_asset_bindings for each row execute function public.command_center_validate_social_draft_asset_binding();
drop trigger if exists command_center_social_draft_approval_binding_validate on public.command_center_social_draft_approval_bindings; create trigger command_center_social_draft_approval_binding_validate before insert on public.command_center_social_draft_approval_bindings for each row execute function public.command_center_validate_social_draft_approval_binding();
create or replace function public.command_center_reject_social_draft_history_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social draft history is immutable'; end $$;
create or replace function public.command_center_reject_social_draft_binding_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social draft bindings are immutable'; end $$;
drop trigger if exists command_center_social_draft_history_immutable on public.command_center_social_draft_revision_history; create trigger command_center_social_draft_history_immutable before update or delete on public.command_center_social_draft_revision_history for each row execute function public.command_center_reject_social_draft_history_mutation();
drop trigger if exists command_center_social_draft_assets_immutable on public.command_center_social_draft_asset_bindings; create trigger command_center_social_draft_assets_immutable before update or delete on public.command_center_social_draft_asset_bindings for each row execute function public.command_center_reject_social_draft_binding_mutation();
drop trigger if exists command_center_social_draft_approvals_immutable on public.command_center_social_draft_approval_bindings; create trigger command_center_social_draft_approvals_immutable before update or delete on public.command_center_social_draft_approval_bindings for each row execute function public.command_center_reject_social_draft_binding_mutation();
alter table public.command_center_social_draft_revision_history enable row level security; alter table public.command_center_social_draft_asset_bindings enable row level security; alter table public.command_center_social_draft_approval_bindings enable row level security;
revoke all on table public.command_center_social_draft_revision_history,public.command_center_social_draft_asset_bindings,public.command_center_social_draft_approval_bindings from public,anon,authenticated;
grant select,insert on table public.command_center_social_draft_revision_history,public.command_center_social_draft_asset_bindings,public.command_center_social_draft_approval_bindings to authenticated; grant select on table public.command_center_social_drafts_current to authenticated;
create policy p10_3_social_draft_owner_select on public.command_center_social_draft_revision_history for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_3_social_draft_owner_insert on public.command_center_social_draft_revision_history for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_3_social_draft_asset_owner_select on public.command_center_social_draft_asset_bindings for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_3_social_draft_asset_owner_insert on public.command_center_social_draft_asset_bindings for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_3_social_draft_approval_owner_select on public.command_center_social_draft_approval_bindings for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_3_social_draft_approval_owner_insert on public.command_center_social_draft_approval_bindings for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
